import os
import urllib
import mimetypes
import logging

log = logging.getLogger(__name__)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            mime = mimetypes.MimeTypes()
            guessed = mime.guess_type(urllib.pathname2url(self.path))
            if guessed[0]:
                self.type = guessed[0]
            else:
                ext = os.path.splitext(self.name)
                if ext[1]:
                    log.warn("Mime type for '%s' is unknown.", self.path)
                self.type = UNKNOWN_MIME_TYPE

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

