@parameterized.parameterized_class([
    {'dst': 'cpu'},
    {'dst': 'gpu'},
    {'dst': 'both'},
])
@testing.inject_backend_tests(None)
class TestCopy(function_tester.FunctionTestCase):

    def setUp(self):
        self.dtype = numpy.float32
        self.check_forward_option = {'rtol': 1e-3, 'atol': 1e-3}

    def forward(self, inputs, backend_config):
        x, = inputs
        dst = self.dst
        if dst == 'gpu':
            if backend_config.xp is not cuda.cupy:
                x = cuda.to_cpu(x)
            out = cuda.empty_like(x)
            cuda.copy(x, out_device=out.device)
        elif dst == 'both':
            if backend_config.xp is not cuda.cupy:
                out = cuda.to_gpu(x)
                cuda.copy(x, out_device=out.device)
            else:
                out = cuda.empty_like(x)
                cuda.copy(x, out_device=out.device)
        else:
            out = x.copy()
        return out,


