import mimetypes
import logging

logger = logging.getLogger(APP_NAME)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            mime = mimetypes.MimeTypes()
            self.type = mime.guess_type(urllib.pathname2url(self.path))[0]

    @staticmethod
    def get_objects(path):
        objects = []
        objects_cache = {}

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                object = Object(object_path)

                if object.type not in objects_cache:
                    objects_cache[object.type] = []

                objects_cache[object.type].append(object)

        for key in objects_cache:
            objects.extend(objects_cache[key])

        return objects


